class FakeClock:
    """Deterministic clock for testing timeout boundaries without real delays."""

    def __init__(self, start: float = 0.0) -> None:
        self._now = start
        self._lock = threading.Lock()

    def monotonic(self) -> float:
        with self._lock:
            return self._now

    def advance(self, delta: float) -> None:
        """Advance the fake clock by `delta` seconds."""
        with self._lock:
            self._now += delta


