class TestAcquireRelease:
    """Core lock/unlock behavior."""

    def test_initial_state_unlocked(self, real_lock: IdentityLock):
        """New lock has no owner."""
        assert real_lock._owner is None

    def test_acquire_sets_owner(self, real_lock: IdentityLock):
        """Acquiring sets owner to current thread ID."""
        real_lock.acquire()
        assert real_lock._owner == threading.get_ident()

    def test_release_clears_owner(self, real_lock: IdentityLock):
        """Releasing clears owner and allows re-acquisition."""
        real_lock.acquire()
        real_lock.release()
        assert real_lock._owner is None

    def test_acquire_release_cycle(self, real_lock: IdentityLock):
        """Multiple acquire/release cycles work."""
        for _ in range(10):
            real_lock.acquire()
            real_lock.release()

    def test_release_without_acquire_raises(self, real_lock: IdentityLock):
        """Releasing an unlocked lock raises RuntimeError."""
        with pytest.raises(RuntimeError):
            real_lock.release()

    def test_release_by_non_owner_raises(self, real_lock: IdentityLock):
        """Only the owning thread can release."""
        real_lock.acquire()
        # Simulate a different thread attempting release
        with pytest.raises(RuntimeError):
            real_lock._release_by_owner(threading.get_ident() + 1)  # type: ignore[attr-defined]
        real_lock.release()

    def test_context_manager(self, real_lock: IdentityLock):
        """Context manager acquires and releases."""
        with real_lock:
            assert real_lock._owner == threading.get_ident()
        assert real_lock._owner is None

    def test_context_manager_release_on_exception(self, real_lock: IdentityLock):
        """Context manager releases even if body raises."""
        with pytest.raises(ValueError):
            with real_lock:
                raise ValueError("boom")
        assert real_lock._owner is None


