class TestTimeout:
    """Precise timeout boundary testing with injected clock."""

    def test_acquire_success_with_timeout(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Acquire succeeds when lock is free, regardless of timeout."""
        lock_with_fake_clock.acquire(timeout=5.0)
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()

    def test_timeout_zero_immediate_contention(self, lock_with_fake_clock: IdentityLock):
        """Zero timeout on contended lock raises LockContentionError immediately."""
        lock_with_fake_clock.acquire()
        with pytest.raises(LockContentionError):
            lock_with_fake_clock.acquire(timeout=0.0)
        lock_with_fake_clock.release()

    def test_negative_timeout_immediate_contention(self, lock_with_fake_clock: IdentityLock):
        """Negative timeout on contended lock raises LockContentionError."""
        lock_with_fake_clock.acquire()
        with pytest.raises(LockContentionError):
            lock_with_fake_clock.acquire(timeout=-1.0)
        lock_with_fake_clock.release()

    def test_timeout_expiry_raises(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """LockTimeoutError raised when timeout elapses without acquisition."""
        lock_with_fake_clock.acquire()
        with pytest.raises(LockTimeoutError):
            lock_with_fake_clock.acquire(timeout=1.0)
            fake_clock.advance(1.0)  # Simulate time passing
        lock_with_fake_clock.release()

    def test_timeout_exact_boundary_success(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Acquisition succeeds exactly at the timeout boundary if lock frees."""
        lock_with_fake_clock.acquire()
        # Simulate another thread releasing at t=0.5
        def release_after_delay():
            fake_clock.advance(0.5)
            lock_with_fake_clock.release()

        t = threading.Thread(target=release_after_delay)
        t.start()
        lock_with_fake_clock.acquire(timeout=1.0)
        t.join()
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()

    def test_timeout_does_not_acquire_after_expiry(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Lock is not acquired if timeout expires before lock becomes free."""
        lock_with_fake_clock.acquire()
        with pytest.raises(LockTimeoutError):
            lock_with_fake_clock.acquire(timeout=0.1)
            fake_clock.advance(0.2)  # Time passes beyond timeout
        # Lock should still be owned by original thread
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()

    def test_timeout_waits_for_release(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Acquire with timeout succeeds if lock released before timeout."""
        lock_with_fake_clock.acquire()
        def release_soon():
            fake_clock.advance(0.2)
            lock_with_fake_clock.release()

        t = threading.Thread(target=release_soon)
        t.start()
        lock_with_fake_clock.acquire(timeout=1.0)
        t.join()
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()


