class TestReentrancy:
    """Non-reentrant behavior enforcement."""

    def test_reentrant_acquire_raises(self, real_lock: IdentityLock):
        """Acquiring an already-owned lock (same thread) raises LockTimeoutError or blocks."""
        real_lock.acquire()
        # With default system clock, this would block; but we can test with fake clock
