class TestConcurrency:
    """Thread-safety under contention."""

    def test_concurrent_acquire_exclusive(self):
        """Only one thread holds the lock at any time."""
        lock = IdentityLock()
        counter = 0
        errors = []

        def worker():
            nonlocal counter
            for _ in range(100):
                lock.acquire()
                # Critical section
                local = counter
                time.sleep(0.0001)  # Force context switch
                counter = local + 1
                lock.release()

        threads = [threading.Thread(target=worker) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert counter == 1000  # 10 threads * 100 iterations
        assert not errors

    def test_concurrent_acquire_with_timeout(self):
        """Concurrent acquisition with timeout never results in two owners."""
        lock = IdentityLock()
        active_owners = []
        max_concurrent = 0
        stop = threading.Event()

        def worker():
            nonlocal max_concurrent
            while not stop.is_set():
                try:
                    lock.acquire(timeout=0.01)
                except (LockTimeoutError, LockContentionError):
                    continue
                with threading.Lock():
                    active_owners.append(threading.get_ident())
                    max_concurrent = max(max_concurrent, len(active_owners))
                time.sleep(0.0001)
                with threading.Lock():
                    active_owners.remove(threading.get_ident())
                lock.release()

        threads = [threading.Thread(target=worker) for _ in range(5)]
        for t in threads:
            t.start()
        time.sleep(0.2)
        stop.set()
        for t in threads:
            t.join()

        assert max_concurrent <= 1  # Never more than one owner

    def test_stress_acquire_release(self):
        """High-frequency acquire/release cycles without deadlock."""
        lock = IdentityLock()
        iterations = 10000

        def worker():
            for _ in range(iterations):
                lock.acquire()
                lock.release()

        threads = [threading.Thread(target=worker) for _ in range(4)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # If we get here without deadlock, test passes
        assert lock._owner is None


