class TestEdgeCases:
    """Unusual inputs and boundary conditions."""

    def test_acquire_with_none_timeout(self, real_lock: IdentityLock):
        """None timeout means block indefinitely (default behavior)."""
        real_lock.acquire(timeout=None)
        assert real_lock._owner == threading.get_ident()
        real_lock.release()

    def test_acquire_with_infinity_timeout(self, real_lock: IdentityLock):
        """Infinite timeout behaves like None (block indefinitely)."""
        real_lock.acquire(timeout=float("inf"))
        assert real_lock._owner == threading.get_ident()
        real_lock.release()

    def test_acquire_with_nan_timeout(self, real_lock: IdentityLock):
        """NaN timeout should raise ValueError (invalid input)."""
        with pytest.raises(ValueError):
            real_lock.acquire(timeout=float("nan"))

    def test_clock_injection_validation(self):
        """Invalid clock (missing monotonic) raises AttributeError."""
        class BadClock:
            pass

        with pytest.raises(AttributeError):
            IdentityLock(clock=BadClock())  # type: ignore[arg-type]

    def test_lock_usable_after_timeout(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Lock remains functional after a timeout error."""
        lock_with_fake_clock.acquire()
        with pytest.raises(LockTimeoutError):
            lock_with_fake_clock.acquire(timeout=0.1)
            fake_clock.advance(0.2)
        lock_with_fake_clock.release()
        # Lock should be free now
        lock_with_fake_clock.acquire()
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()

    def test_multiple_timeout_attempts(self, lock_with_fake_clock: IdentityLock, fake_clock: FakeClock):
        """Multiple failed acquisition attempts don't corrupt state."""
        lock_with_fake_clock.acquire()
        for _ in range(5):
            with pytest.raises(LockTimeoutError):
                lock_with_fake_clock.acquire(timeout=0.1)
                fake_clock.advance(0.2)
        assert lock_with_fake_clock._owner == threading.get_ident()
        lock_with_fake_clock.release()


